/**
 * Countries and their states/provinces for the Assistant's dropdowns.
 * The data is generated by scripts/build-regions.mjs (see there for sources).
 */

import data from "./regions.json";
import { resolveIso2 } from "@/lib/data/adapters/countries";

export interface Region {
  /** ISO 3166-2 code, e.g. "US-AZ". */
  code: string;
  name: string;
}

export interface Country {
  /** ISO 3166-1 alpha-2 code, e.g. "US". */
  code: string;
  name: string;
  /** Present only for countries whose first-level divisions are states/provinces. */
  regions?: Region[];
}

export const COUNTRIES: Country[] = (data as { countries: Country[] }).countries;

const byCode = new Map(COUNTRIES.map((c) => [c.code, c]));

/** Lowercase, accent-free, punctuation-free, for forgiving name matches. */
function norm(s: string): string {
  return s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

const byName = new Map(COUNTRIES.map((c) => [norm(c.name), c.code]));

export function countryByCode(code: string | null | undefined): Country | undefined {
  return code ? byCode.get(code.toUpperCase()) : undefined;
}

/** ISO alpha-2 for a country name, alias ("USA", "UK") or code; null if unknown. */
export function countryCodeFor(nameOrCode: string | null | undefined): string | null {
  const s = (nameOrCode || "").trim();
  if (!s) return null;
  if (/^[A-Za-z]{2}$/.test(s) && byCode.has(s.toUpperCase())) return s.toUpperCase();
  const hit = byName.get(norm(s));
  if (hit) return hit;
  const iso = resolveIso2(s, null);
  return iso && byCode.has(iso) ? iso : null;
}

/** The country's states/provinces, or [] when it doesn't use them. */
export function regionsOf(countryCode: string | null | undefined): Region[] {
  return countryByCode(countryCode)?.regions ?? [];
}

// Words that differ between sources ("Aichi" vs "Aichi Prefecture").
const REGION_NOISE = /\b(state|province|prefecture|region|canton|territory|emirate)\b/g;

/** Find a state/province by ISO code ("US-AZ") or by name ("Arizona", "Lagos State"). */
export function findRegion(countryCode: string | null | undefined, codeOrName: string | null | undefined): Region | undefined {
  const regions = regionsOf(countryCode);
  const s = (codeOrName || "").trim();
  if (!regions.length || !s) return undefined;
  const upper = s.toUpperCase();
  const byIso = regions.find((r) => r.code === upper);
  if (byIso) return byIso;
  const key = norm(s).replace(REGION_NOISE, "").trim();
  return regions.find((r) => norm(r.name) === norm(s)) ?? regions.find((r) => norm(r.name).replace(REGION_NOISE, "").trim() === key);
}
